"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7723],{60515:e=>{e.exports=JSON.parse('{"functions":[{"name":"CreateTween","desc":"Returns an unplayed [Tween] and the [NumberValue] it drives.\\n\\nThe NumberValue is parentless and unnamed; nothing else references it, so it is\\ncollected once the caller drops both returns. The tween is **not** started \u2014\\ncall `:Play()` yourself.\\n\\n```lua\\nlocal tween, value = CreateTween(0, 100, TweenInfo.new(2))\\n\\nvalue:GetPropertyChangedSignal(\\"Value\\"):Connect(function()\\n\\tbar.Size = UDim2.fromScale(value.Value / 100, 1)\\nend)\\n\\ntween:Play()\\n```","params":[{"name":"start","desc":"Starting value (defaults to 0)","lua_type":"number?"},{"name":"goal","desc":"Value to tween to","lua_type":"number"},{"name":"tweenInfo","desc":"Falls back to a 1.2s linear tween when nil","lua_type":"TweenInfo"}],"returns":[{"desc":"","lua_type":"(Tween, NumberValue)"}],"function_type":"static","source":{"line":41,"path":"src/Shared/Class/CreateTween.luau"}}],"properties":[],"types":[],"name":"CreateTween","desc":"Tweens a plain number by animating a throwaway [NumberValue], since TweenService\\ncan only tween instance properties.\\n\\nThe caller listens to the NumberValue\'s `Value` for each step. For the common case\\nof driving a [TextLabel], use [CreateNumberTween] instead, which wraps this.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":13,"path":"src/Shared/Class/CreateTween.luau"}}')}}]);